<script setup>import {computed,ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from '../services/api';import ProductCard from '../components/ProductCard.vue';const route=useRoute(),router=useRouter();const products=ref([]),categories=ref([]),brands=ref([]),loading=ref(false);const filters=ref({search:'',category:route.query.category||'',brand:'',minPrice:'',maxPrice:'',stock:'',sort:'featured'});async function load(){loading.value=true;const r=await api.products({...filters.value,limit:100});products.value=r.data;brands.value=r.meta.brands;loading.value=false}onMounted(async()=>{categories.value=(await api.categories()).data;await load()});watch(()=>route.query.category,v=>{filters.value.category=v||'';load()});watch(filters,()=>{const q={...route.query};Object.entries(filters.value).forEach(([k,v])=>{if(v)q[k]=v;else delete q[k]});router.replace({query:q});load()},{deep:true});const count=computed(()=>products.value.length);function reset(){filters.value={search:'',category:'',brand:'',minPrice:'',maxPrice:'',stock:'',sort:'featured'}};</script>
<template><section class="shop-page"><div class="breadcrumbs">Home / Shop <span v-if="filters.category">/ {{categories.find(c=>c.slug===filters.category)?.name}}</span></div><div class="shop-title"><div><span class="eyebrow">CATALOG</span><h1>{{filters.category?categories.find(c=>c.slug===filters.category)?.name:'Shop All'}}</h1><p>{{count}} precision-engineered models found.</p></div><select v-model="filters.sort"><option value="featured">Sort by: Featured</option><option value="newest">Newest</option><option value="price-asc">Price: Low to High</option><option value="price-desc">Price: High to Low</option></select></div><div class="shop-layout"><aside class="filters"><div class="filter-head"><b>Filters</b><button @click="reset">Clear All</button></div><label>Search<input v-model="filters.search" placeholder="components, devices..."/></label><label>Category<select v-model="filters.category"><option value="">All categories</option><option v-for="c in categories" :value="c.slug">{{c.name}}</option></select></label><label>Brand<select v-model="filters.brand"><option value="">All brands</option><option v-for="b in brands" :value="b">{{b}}</option></select></label><div class="price-row"><label>Min price<input v-model="filters.minPrice" type="number" placeholder="0"/></label><label>Max price<input v-model="filters.maxPrice" type="number" placeholder="2499"/></label></div><label class="check"><input v-model="filters.stock" value="in" type="checkbox"> In stock</label></aside><div class="results"><div v-if="loading" class="empty">Loading catalog…</div><div v-else-if="!products.length" class="empty">No products match the selected filters.</div><div v-else class="product-grid"><ProductCard v-for="p in products" :key="p.id" :product="p"/></div></div></div></section></template>
